// import logo from "../assets/Logo.jpg";

import { useEffect, useState } from "react";
import "../styles/Navbar.css";

const Navbar = ({ currentBackground, onBackgroundChange }) => {
  const [showNavbar, setShowNavbar] = useState(false);
  const navItems = [
    { name: "About", link: "#about-section", icon: "" },
    { name: "Services", link: "#services", icon: "" },
    { name: "Projects", link: "#projects", icon: "" },
    { name: "Contact", link: "#contact", icon: "" }
  ];

  const scrollToSection = (sectionId, e) => {
    e.preventDefault();
    const section = document.getElementById(sectionId);
    if (section) {
      const navHeight = 80; // Height of fixed navbar
      const sectionTop = section.offsetTop - navHeight;
      window.scrollTo({
        top: sectionTop,
        behavior: 'smooth'
      });
    }
  };

  return (
    <nav className="nav">
      <div className="nav-container">
        <div className="nav-logo">
          <a href='#about-section' onClick={(e) => scrollToSection('about-section', e)}>
            {/* <img src={logo} alt="Kushal" className="w-10 h-10 rounded-full" /> */}
            <span className="logo-text">Kushal</span>
          </a>
        </div>
        <div className="nav-menu">
          {navItems.map((item, index) => (
            <a
              key={index}
              href={item.link}
              className="nav-link"
              onClick={(e) => scrollToSection(item.link.replace('#', ''), e)}
            >
              {item.name}
            </a>
          ))}
          <a 
            href="/resume.pdf" 
            download 
            className="nav-resume-btn"
          >
            Resume
          </a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
